query:
SELECT DISTINCT ?city ?cityLabel ?oktmo ?coverage ?coord WHERE {
  hint:Query hint:optimizer "None" .
  {
    VALUES ?cls { wd:Q7930989 wd:Q515 wd:Q106389302 wd:Q1549591 wd:Q1637706 wd:Q5123997 }
    ?st ps:P31 ?cls .
    ?city p:P31 ?st .
    FILTER NOT EXISTS { ?st wikibase:rank wikibase:DeprecatedRank . }
    FILTER NOT EXISTS { ?st pq:P582 ?ended . }
    FILTER NOT EXISTS {
      ?st wikibase:rank wikibase:NormalRank .
      ?city p:P31 ?rst .
      ?rst wikibase:rank wikibase:PreferredRank ; ps:P31 ?rural .
      VALUES ?rural { wd:Q532 wd:Q5084 wd:Q2514025 wd:Q2023000 wd:Q748331 wd:Q15078955 wd:Q20019082 }
    }
    ?city wdt:P17 wd:Q159 ;
          wdt:P764 ?oktmo .
    BIND("p17_russia" AS ?coverage)
  } UNION {
    ?city wdt:P764 ?oktmo .
    FILTER NOT EXISTS { ?city wdt:P17 wd:Q159 . }
    ?city p:P31/ps:P31/wdt:P279* wd:Q7930989 .
    BIND("oktmo_only" AS ?coverage)
  }
  OPTIONAL { ?city wdt:P625 ?coord . }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "ru,en". }
}
